def policy(obs,P):
    x,y,vx,vy,angle,ang_v,leg_left,leg_right = obs
    # landed with leg contact and slow descent -> noop
    if leg_left > P['leg_thr'] and y < P['y_low'] and vy > P['vy_fast']:
        return 0
    # high altitude fast fall -> noop (tree 100%)
    if y > P['y_high'] and vy < P['vy_fast']:
        return 0
    # very low altitude falling -> main to soften
    if y < P['y_vlow'] and vy < P['vy_thr']:
        return 2
    # strong horizontal error overrides attitude when large
    if x < -P['x_thr']*1.2 or vx < -P['vx_thr']*1.5:
        return 3
    if x > P['x_thr']*1.2 or vx > P['vx_thr']*1.5:
